package work.fking.nexnostalgia;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(NexNostalgiaConfig.GROUP)
public interface NexNostalgiaConfig extends Config {

    String GROUP = "nexNostalgia";
    String KEY_EXTRA_VO_VOLUME = "extraVoVolume";
    String KEY_ANIM_SMOOTHING = "enableAnimSmoothing";

    @ConfigItem(
            keyName = KEY_EXTRA_VO_VOLUME,
            name = "Extra Volume",
            description = "The extra volume to be applied to Voice Overs."
    )
    @Range(min = -25, max = 75)
    default int extraVoVolume() {
        return 10;
    }

    @ConfigItem(
            keyName = KEY_ANIM_SMOOTHING,
            name = "Selective Anim Smoothing",
            description = "Selectively enables animation smoothing for Nex & Blood Reavers animations"
    )
    default boolean enableAnimSmoothing() {
        return false;
    }
}

package work.fking.nexnostalgia;

import com.google.inject.Provides;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.CommandExecuted;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.AnimationID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.plugins.animsmoothing.AnimationSmoothingPlugin;
import net.runelite.client.util.Text;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import javax.inject.Inject;
import javax.inject.Named;
import javax.sound.sampled.LineUnavailableException;

@PluginDescriptor(name = "Nex Nostalgia")
public class NexNostalgiaPlugin extends Plugin {

    private static final Logger LOGGER = LoggerFactory.getLogger(NexNostalgiaPlugin.class);
    private static final int MAX_CONCURRENT_SOUNDS = 5;

    private SoundPlayer soundPlayer;

    @Inject
    private Client client;

    @Inject
    private ClientThread clientThread;

    @Inject
    private NexNostalgiaConfig config;

    @Inject
    private PluginManager pluginManager;

    @Inject
    private AnimationSmoothingPlugin animationSmoothingPlugin;

    @Inject
    private ChatMessageManager chatMessageManager;

    @Inject
    @Named("developerMode")
    private boolean developerMode;

    @Override
    protected void startUp() {
        if (soundPlayer == null || soundPlayer.isShutdown()) {
            try {
                soundPlayer = new SoundPlayer(MAX_CONCURRENT_SOUNDS);
                clientThread.invokeLater(this::updateSoundPlayerVolume);
            } catch (LineUnavailableException e) {
                LOGGER.warn("Could not open audio output line, SoundPlayer will be disabled", e);
            }
        }

        if (config.enableAnimSmoothing()) {
            setupAnimSmoothingFilter();
        }
    }

    @Override
    protected void shutDown() {
        if (soundPlayer != null) {
            soundPlayer.shutdown();
        }

        if (config.enableAnimSmoothing()) {
            tearDownAnimSmoothingFilter();
        }
    }

    @Provides
    NexNostalgiaConfig provideConfig(ConfigManager configManager) {
        return configManager.getConfig(NexNostalgiaConfig.class);
    }

    @Subscribe
    public void onCommandExecuted(CommandExecuted command) {
        var arguments = command.getArguments();

        if (!developerMode || !command.getCommand().equals("vo")) {
            return;
        }
        if (arguments.length < 1) {
            return;
        }
        var voiceOverName = arguments[0].toUpperCase();

        try {
            var voiceOver = VoiceOver.valueOf(voiceOverName);
            client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "Playing voiceover " + voiceOver, null);

            playVoiceOver(voiceOver);
        } catch (IllegalArgumentException e) {
            client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "Unknown voiceover: " + voiceOverName, null);
        }
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event) {
        if (!NexNostalgiaConfig.GROUP.equals(event.getGroup())) {
            return;
        }

        switch (event.getKey()) {
            case NexNostalgiaConfig.KEY_EXTRA_VO_VOLUME:
                clientThread.invokeLater(this::updateSoundPlayerVolume);
                break;
            case NexNostalgiaConfig.KEY_ANIM_SMOOTHING:
                if (config.enableAnimSmoothing()) {
                    setupAnimSmoothingFilter();
                } else {
                    tearDownAnimSmoothingFilter();
                }
                break;
        }
    }

    @Subscribe
    public void onChatMessage(ChatMessage event) {
        if (event.getType() != ChatMessageType.NPC_SAY) {
            return;
        }
        var text = Text.removeTags(event.getMessage());

        if (!text.startsWith("Nex|")) {
            return;
        }
        var voiceOver = VoiceOver.forTriggerLine(text.substring(4));

        if (voiceOver != null) {
            playVoiceOver(voiceOver);
        }
    }

    @Subscribe
    public void onVarbitChanged(VarbitChanged event) {
        var varpId = event.getVarpId();
        if (varpId != VarPlayerID.OPTION_SOUNDS && varpId != VarPlayerID.OPTION_MASTER_VOLUME) {
            return;
        }
        updateSoundPlayerVolume();
    }

    // Must be called from within client thread
    private void updateSoundPlayerVolume() {
        if (soundPlayer == null) {
            return;
        }
        var masterVolume = client.getVarpValue(VarPlayerID.OPTION_MASTER_VOLUME);
        var soundVolume = client.getVarpValue(VarPlayerID.OPTION_SOUNDS);
        var effectiveSoundVolume = soundVolume * masterVolume / 100;

        soundPlayer.setMasterVolume(effectiveSoundVolume + config.extraVoVolume());
    }

    private void playVoiceOver(VoiceOver voiceOver) {
        if (soundPlayer != null) {
            soundPlayer.play(voiceOver);
        }
    }

    private boolean isAnimSmoothingPluginEnabled() {
        return pluginManager.isPluginEnabled(animationSmoothingPlugin);
    }

    private void tearDownAnimSmoothingFilter() {
        if (isAnimSmoothingPluginEnabled()) {
            return;
        }
        client.setAnimationInterpolationFilter(null);
    }

    private void setupAnimSmoothingFilter() {
        if (isAnimSmoothingPluginEnabled()) {
            var formattedMessage = new ChatMessageBuilder()
                    .append(ChatColorType.HIGHLIGHT)
                    .append("[Nex Nostalgia] Selective animation was not enabled, Animation Smoothing plugin is active.")
                    .build();

            chatMessageManager.queue(QueuedMessage.builder()
                                                  .type(ChatMessageType.CONSOLE)
                                                  .runeLiteFormattedMessage(formattedMessage)
                                                  .build());
            return;
        }
        client.setAnimationInterpolationFilter(animId -> {
            switch (animId) {
                case AnimationID.NEX_RUN:
                case AnimationID.NEX_PET_RUN:
                case AnimationID.NEX_READY:
                case AnimationID.NEX_DASH_ATTACK:
                case AnimationID.NEX_TURMOIL:
                case AnimationID.NEX_ATTACK:
                case AnimationID.NEX_PET_ATTACK:
                case AnimationID.NEX_BLAST_AWAY:
                case AnimationID.NEX_BLOOD_SIPHON:
                case AnimationID.NEX_DEATH:
                case AnimationID.NEX_DEFEND:
                case AnimationID.NEX_SMASH_ATTACK:
                case AnimationID.NEX_SPIN_OUT:
                case AnimationID.NEX_ALTERNATE_CAST_ATTACK:
                case AnimationID.NEX_CAST_ATTACK:

                case AnimationID.BLOOD_REAVER_DEATH:
                case AnimationID.BLOOD_REAVER_WALK:
                case AnimationID.BLOOD_REAVER_ATTACK:
                case AnimationID.BLOOD_REAVER_READY:
                case AnimationID.BLOOD_REAVER_DEFEND:

                case AnimationID.NEX_MUSHROOM_CLOUD_PROJANIM:
                case AnimationID.NEX_MUSHROOM_CLOUD_SPOTANIM:

                case AnimationID.NEX_SUMMON:
                    return true;
                default:
                    return false;
            }
        });
    }
}

package work.fking.nexnostalgia;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import javax.sound.sampled.AudioFormat;
import javax.sound.sampled.AudioInputStream;
import javax.sound.sampled.AudioSystem;
import javax.sound.sampled.LineUnavailableException;
import javax.sound.sampled.SourceDataLine;
import javax.sound.sampled.UnsupportedAudioFileException;
import java.io.BufferedInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.concurrent.ArrayBlockingQueue;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.atomic.AtomicInteger;

public class SoundPlayer {

    private static final Logger LOGGER = LoggerFactory.getLogger(SoundPlayer.class);

    private static final AudioFormat OUTPUT_FORMAT = new AudioFormat(44100, 16, 2, true, false);

    public static final int MIN_VOLUME_PERCENT = 0;
    public static final int MAX_VOLUME_PERCENT = 125;

    private static final int BUFFER_FRAMES = 1024;
    private static final int BUFFER_SIZE = BUFFER_FRAMES * OUTPUT_FORMAT.getFrameSize();

    private final BlockingQueue<VoiceOver> pendingQueue;
    private final BlockingQueue<PlayingVoiceOver> readyQueue;

    private final AtomicInteger masterVolume = new AtomicInteger(100);

    private volatile boolean shutdown = false;

    private final Thread loaderThread;
    private final Thread mixerThread;
    private final SourceDataLine line;

    public SoundPlayer(int queueCapacity) throws LineUnavailableException {
        this.pendingQueue = new ArrayBlockingQueue<>(queueCapacity);
        this.readyQueue = new ArrayBlockingQueue<>(queueCapacity);
        this.line = openLine();

        this.loaderThread = new Thread(this::loaderLoop, "NexNostalgia-SoundPlayer-Loader");
        this.loaderThread.setDaemon(true);
        this.loaderThread.start();

        this.mixerThread = new Thread(this::mixerLoop, "NexNostalgia-SoundPlayer-Mixer");
        this.mixerThread.setDaemon(true);
        this.mixerThread.start();
    }

    public boolean isShutdown() {
        return shutdown;
    }

    public void shutdown() {
        shutdown = true;
        loaderThread.interrupt();
        mixerThread.interrupt();
    }

    public void setMasterVolume(int volume) {
        masterVolume.set(Math.max(MIN_VOLUME_PERCENT, Math.min(MAX_VOLUME_PERCENT, volume)));
    }

    public void play(VoiceOver voiceOver) {
        if (shutdown) {
            return;
        }
        if (!pendingQueue.offer(voiceOver)) {
            LOGGER.debug("Sound queue full, dropping voiceOver={}", voiceOver);
        }
    }

    private void mixerLoop() {
        List<PlayingVoiceOver> playingVoiceOvers = new ArrayList<>();

        try (line) {
            line.start();

            var mixBuffer = new int[BUFFER_FRAMES * OUTPUT_FORMAT.getChannels()];
            var outBuffer = new byte[BUFFER_SIZE];

            while (!shutdown) {
                drainReadyQueueTo(playingVoiceOvers);

                if (playingVoiceOvers.isEmpty()) {
                    try {
                        playingVoiceOvers.add(readyQueue.take());
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                    }
                    continue;
                }
                Arrays.fill(mixBuffer, 0);

                var masterGain = masterVolume.get() / 100.0f;
                var it = playingVoiceOvers.iterator();

                while (it.hasNext()) {
                    var sound = it.next();
                    if (sound.mixInto(mixBuffer, masterGain)) {
                        sound.close();
                        it.remove();
                    }
                }

                for (int i = 0; i < BUFFER_FRAMES; i++) {
                    var sampleLeft = clamp(mixBuffer[i * 2]);
                    var sampleRight = clamp(mixBuffer[i * 2 + 1]);

                    outBuffer[i * 4] = (byte) (sampleLeft & 0xFF);
                    outBuffer[i * 4 + 1] = (byte) ((sampleLeft >> 8) & 0xFF);
                    outBuffer[i * 4 + 2] = (byte) (sampleRight & 0xFF);
                    outBuffer[i * 4 + 3] = (byte) ((sampleRight >> 8) & 0xFF);
                }
                line.write(outBuffer, 0, BUFFER_SIZE);
            }

            line.drain();
            line.stop();
        } finally {
            clearReadyQueue();
            playingVoiceOvers.forEach(PlayingVoiceOver::close);
        }
    }

    private void drainReadyQueueTo(List<PlayingVoiceOver> playingVoiceOvers) {
        PlayingVoiceOver sound;
        while ((sound = readyQueue.poll()) != null) {
            playingVoiceOvers.add(sound);
        }
    }

    private void clearReadyQueue() {
        PlayingVoiceOver queued;
        while ((queued = readyQueue.poll()) != null) {
            queued.close();
        }
    }

    private void loaderLoop() {
        while (!shutdown) {
            var pendingVoiceOver = takeNextVoiceOver();

            if (pendingVoiceOver == null) {
                continue;
            }
            var stream = getClass().getResourceAsStream("/sounds/" + pendingVoiceOver.file());

            if (stream == null) {
                continue;
            }
            var pcmStream = toPcmStream(stream);

            if (pcmStream == null) {
                closeQuietly(stream);
                continue;
            }

            if (!readyQueue.offer(new PlayingVoiceOver(pcmStream))) {
                LOGGER.debug("Failed to queue voice over, readyQueue is full");
                closeQuietly(pcmStream);
                closeQuietly(stream);
            }
        }
    }

    private VoiceOver takeNextVoiceOver() {
        try {
            return pendingQueue.take();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            return null;
        }
    }

    private AudioInputStream toPcmStream(InputStream stream) {
        AudioInputStream rawStream = null;
        try {
            var bufferedStream = new BufferedInputStream(stream);
            rawStream = AudioSystem.getAudioInputStream(bufferedStream);

            return AudioSystem.getAudioInputStream(OUTPUT_FORMAT, rawStream);
        } catch (UnsupportedAudioFileException | IOException e) {
            LOGGER.warn("Failed to decode audio stream: {}", e.getMessage());
        } catch (IllegalArgumentException e) {
            LOGGER.info("Failed to convert audio stream to specified format: {}", e.getMessage());
        }

        if (rawStream != null) {
            closeQuietly(rawStream);
        }
        return null;
    }

    private void closeQuietly(InputStream inputStream) {
        try {
            inputStream.close();
        } catch (IOException e) {
            // ignore
        }
    }

    private static SourceDataLine openLine() throws LineUnavailableException {
        var line = AudioSystem.getSourceDataLine(OUTPUT_FORMAT);
        line.open(OUTPUT_FORMAT, BUFFER_SIZE * 2);
        return line;
    }

    private static int clamp(int value) {
        return Math.max(Short.MIN_VALUE, Math.min(Short.MAX_VALUE, value));
    }

    private static final class PlayingVoiceOver {

        private final AudioInputStream pcmStream;
        private final byte[] readBuf;

        PlayingVoiceOver(AudioInputStream pcmStream) {
            this.pcmStream = pcmStream;
            this.readBuf = new byte[BUFFER_SIZE];
        }

        boolean mixInto(int[] mixBuffer, float masterGain) {
            var bytesNeeded = SoundPlayer.BUFFER_FRAMES * OUTPUT_FORMAT.getFrameSize();
            int bytesRead = 0;
            try {
                while (bytesRead < bytesNeeded) {
                    var n = pcmStream.read(readBuf, bytesRead, bytesNeeded - bytesRead);
                    if (n == -1) {
                        break;
                    }
                    bytesRead += n;
                }
            } catch (IOException e) {
                LOGGER.warn("Error reading audio stream: {}", e.getMessage());
                return true;
            }
            var samplesRead = bytesRead / 2;

            for (int i = 0; i < samplesRead; i++) {
                var lo = readBuf[i * 2] & 0xFF;
                var hi = readBuf[i * 2 + 1] & 0xFF;
                var sample = (short) (lo | (hi << 8));
                mixBuffer[i] += (int) (sample * masterGain);
            }
            return bytesRead < bytesNeeded;
        }

        void close() {
            try {
                pcmStream.close();
            } catch (IOException e) {
                // ignore
            }
        }
    }
}

package work.fking.nexnostalgia;

import java.util.HashMap;
import java.util.Map;

public enum VoiceOver {

    SIPHON("A siphon will solve this!", "a_siphon_will_solve_this.wav"),
    AT_LAST("AT LAST!", "at_last.wav"),
    CONTAIN_THIS("Contain this!", "contain_this.wav"),
    CRUOR("Cruor!", "cruor.wav"),
    CRUOR_FAIL("Cruor, don't fail me!", "cruor_dont_fail_me.wav"),
    DARKEN_SHADOW("Darken my shadow!", "darken_my_shadow.wav"),
    BLOOD_SACRIFICE("I demand a blood sacrifice!", "demand_blood_sacrifice.wav"),
    PRISON_OF_ICE("Die now, in a prison of ice!", "die_now_in_prison_of_ice.wav"),
    EMBRACE_DARKNESS("Embrace darkness!", "embrace_darkness.wav"),
    FEAR_THE_SHADOW("Fear the shadow!", "fear_the_shadow.wav"),
    SOUL_WITH_SMOKE("Fill my soul with smoke!", "fill_my_soul_with_smoke.wav"),
    FLOOD_MY_LUNGS("Flood my lungs with blood!", "flood_my_lungs_with_blood.wav"),
    FUMUS("Fumus!", "fumus.wav"),
    FUMUS_FAIL("Fumus, don't fail me!", "fumus_dont_fail_me.wav"),
    GLACIES("Glacies!", "glacies.wav"),
    GLACIES_FAIL("Glacies, don't fail me!", "glacies_dont_fail_me.wav"),
    POWER_OF_ICE("Infuse me with the power of ice!", "infuse_me_withe_power_of_ice.wav"),
    NO_ESCAPE("NO ESCAPE!", "no_escape.wav"),
    POWER_OF_ZAROS("NOW, THE POWER OF ZAROS!", "now_the_power_of_zaros.wav"),
    TASTE_MY_WRATH("Taste my wrath!", "taste_my_wrath.wav"),
    THERE_IS("There is...", "there_is.wav"),
    UMBRA("Umbra!", "umbra.wav"),
    UMBRA_FAIL("Umbra, don't fail me!", "umbra_dont_fail_me.wav"),
    VIRUS_FLOW("Let the virus flow through you!", "virus_flow_through_you.wav");

    private static final Map<String, VoiceOver> triggerLines = new HashMap<>();

    static {
        for (VoiceOver voiceOver : values()) {
            triggerLines.put(voiceOver.triggerLine, voiceOver);
        }
    }

    private final String triggerLine;
    private final String file;

    VoiceOver(String triggerLine, String file) {
        this.triggerLine = triggerLine;
        this.file = file;
    }

    public static VoiceOver forTriggerLine(String triggerLine) {
        return triggerLines.get(triggerLine);
    }

    public String file() {
        return file;
    }
}

